// ---------------------------------------------------------------------------
// Loading & caching
// ---------------------------------------------------------------------------
const CACHES = new WeakMap();

function validBank(b) {
  return b && typeof b === 'object' && b.situations && typeof b.situations === 'object';
}

/** Loads a bank ('none' or a sign id) through `loadSign`, cached per loader. Never throws. */
export async function getBank(id, loadSign) {
  if (typeof loadSign !== 'function' || !(id === 'none' || SIGN_IDS.includes(id))) return null;
  let cache = CACHES.get(loadSign);
  if (!cache) { cache = new Map(); CACHES.set(loadSign, cache); }
  if (!cache.has(id)) {
    const p = Promise.resolve()
      .then(() => loadSign(id))
      .then(m => (m && m.default && !m.situations ? m.default : m))
      .then(b => {
        if (!validBank(b)) throw new Error('invalid bank');
        return b;
      })
      .catch(() => { cache.delete(id); return null; }); // retry later: files may still be arriving
    cache.set(id, p);
  }
  return cache.get(id);
}

// ---------------------------------------------------------------------------
// Deterministic variant selection
// ---------------------------------------------------------------------------
export function hash(str) {
  let h = 0x811c9dc5;
  const s = String(str);
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return h >>> 0;
}

function seedNumber(seed) {
  if (seed === undefined || seed === null || seed === '') return 0;
  const n = Number(seed);
  if (Number.isFinite(n)) return Math.abs(Math.trunc(n)) % 1000003;
  return hash(String(seed)) % 1000003;
}

/**
 * Picks one index per slot. Slots form a mixed-radix number; each seed step adds 1 to every
 * digit (plus carry), so consecutive seeds change every slot with ≥3 variants.
 */
export function pickIndices(sizes, key, seed) {
  const n = sizes.map(x => Math.max(1, x | 0));
  let total = 1; const place = [];
  for (const x of n) { place.push(total); total *= x; }
  const K = place.reduce((a, b) => a + b, 0);
  const base = hash(key) % total;
  const c = (base + (seedNumber(seed) % total) * K) % total;
  return n.map((x, i) => Math.floor(c / place[i]) % x);
}

