const L = lang => (lang === 'en' ? 'en' : 'it');
const arr = v => (Array.isArray(v) ? v.filter(x => typeof x === 'string' && x.trim()) : []);

function field(bank, situation, lang, key) {
  return arr(bank && bank.situations && bank.situations[situation] && bank.situations[situation][lang] && bank.situations[situation][lang][key]);
}

const STOP = new Set('il lo la i gli le un una di a da in con su per tra fra e o ma che non si ti mi ci ne del della dei è the a an and or but to of in on for with is it you your they them that this be not'.split(' '));
function words(s) { return new Set(normalize(s).split(/[^a-z']+/).filter(w => w.length > 2 && !STOP.has(w))); }
function overlaps(a, b) {
  const A = words(a); const B = words(b);
  if (!A.size || !B.size) return false;
  let inter = 0; for (const w of B) if (A.has(w)) inter++;
  return inter / Math.min(A.size, B.size) >= 0.5 || normalize(a).includes(normalize(b));
}

function fill(template, sign, lang) {
  return sign ? template.replace(/\{sign\}/g, SIGN_NAMES[lang][sign]) : template;
}

