/**
 * Offline analysis of a situation.
 * @returns {Promise<null | {summary, whatsHappening, strategy, avoid, message, detectedSign,
 *   situation, relation, pairing, keyInsight, confidence, lowConfidence, userSign, usedBank, complete}>}
 * Fields may be '' when the bank for them is missing; `complete` tells whether all contract fields are filled.
 */
export async function analyzeSituation({ text = '', lang = 'it', knownSign = '', userSign = '', seed = 0, loadSign } = {}) {
  const lg = L(lang);
  const d = detect(text, lg);
  const sign = toSignId(knownSign) || d.sign || '';
  const mine = toSignId(userSign) || d.selfSign || '';
  const situation = d.situation;

  const [none, own] = await Promise.all([getBank('none', loadSign), sign ? getBank(sign, loadSign) : null]);
  if (!none && !own) return null;

  const pick = key => {
    const a = field(own, situation, lg, key);
    return a.length ? { list: a, from: sign } : { list: field(none, situation, lg, key), from: 'none' };
  };
  const lists = Object.fromEntries(FIELDS.map(k => [k, pick(k)]));
  const summaries = arr(none && none.summary && none.summary[situation] && none.summary[situation][lg]);
  const insightKey = INSIGHT_KEY[situation];
  const insights = arr(own && own.profile && own.profile[lg] && own.profile[lg][insightKey]);
  const pairAvailable = sign && mine && ELEMENT[sign] && ELEMENT[mine];
  const pairSize = pairAvailable ? PAIRS[`${ELEMENT[mine]}>${ELEMENT[sign]}`][lg].length : 1;

  const sizes = [summaries.length, ...FIELDS.map(k => lists[k].list.length), insights.length, pairSize];
  const idx = pickIndices(sizes, `${normalize(text)}|${sign}|${situation}|${lg}`, seed);
  // never the same index for all four main fields
  const main = idx.slice(1, 5);
  if (main.every(i => i === main[0]) && lists.message.list.length > 1) idx[4] = (idx[4] + 1) % lists.message.list.length;

  const out = {};
  out.summary = summaries.length ? summaries[idx[0]] : '';
  FIELDS.forEach((k, i) => { const l = lists[k].list; out[k] = l.length ? fill(l[idx[i + 1]], sign, lg) : ''; });

  let keyInsight = '';
  if (insights.length && sign) {
    const line = insights[idx[5]];
    if (!overlaps(out.strategy, line)) keyInsight = `${INSIGHT_LABEL[lg][insightKey](SIGN_NAMES[lg][sign])} ${lowerFirst(line, lg)}`;
  }
  if (keyInsight && out.strategy) out.strategy = `${out.strategy}\n\n${keyInsight}`;

  const pairing = pairAvailable ? pairingLine(mine, sign, lg, idx[6]) : '';
  return {
    ...out,
    detectedSign: sign,
    situation,
    relation: d.relation,
    pairing,
    keyInsight,
    confidence: d.confidence,
    lowConfidence: d.lowConfidence,
    userSign: mine,
    usedBank: lists.whatsHappening.from,
    complete: ['summary', ...FIELDS].every(k => out[k])
  };
}

function lowerFirst(s, lang) {
  // keep capitals of proper names / "I"; only lower a plain first word
  if (!s) return s;
  if (lang === 'en' && /^I\b/.test(s)) return s;
  const first = s.split(/\s/)[0];
  if (Object.values(SIGN_NAMES[lang]).some(n => first.startsWith(n))) return s;
  return s[0].toLowerCase() + s.slice(1);
}

/** Offline coach strategy after a message was sent. Returns {strategy, sign} or null. */
export async function coachStrategy({ followupType, lang = 'it', sign = '', seed = 0, text = '', loadSign } = {}) {
  const lg = L(lang);
  const type = FOLLOWUPS.includes(followupType) ? followupType : 'seen';
  const id = toSignId(sign);
  const pickFrom = b => arr(b && b.coach && b.coach[type] && b.coach[type][lg]);
  let list = []; let from = '';
  if (id) { list = pickFrom(await getBank(id, loadSign)); from = id; }
  if (!list.length) { list = pickFrom(await getBank('none', loadSign)); from = ''; }
  if (!list.length) return null;
  const [i] = pickIndices([list.length], `${type}|${id}|${normalize(text)}|${lg}`, seed);
  return { strategy: fill(list[i], from, lg), sign: from };
}

/**
 * Grounding for the AI prompt: detected situation + the sign's profile lines, as plain text.
 * Returns {text, situation, relation, sign, userSign}.
 */
export async function groundingContext({ text = '', lang = 'it', knownSign = '', userSign = '', loadSign } = {}) {
  const lg = L(lang);
  const d = detect(text, lg);
  const sign = toSignId(knownSign) || d.sign || '';
  const mine = toSignId(userSign) || d.selfSign || '';
  const bank = sign ? await getBank(sign, loadSign) : null;
  const lines = [];
  const sit = SITUATION_LABEL[lg][d.situation];
  if (lg === 'it') {
    lines.push(`Situazione rilevata automaticamente: ${sit}${d.lowConfidence ? ' (stima incerta: verifica sul testo)' : ''}.`);
    if (d.relation !== 'unknown') lines.push(`Relazione probabile: ${REL_LABEL.it[d.relation]}.`);
  } else {
    lines.push(`Automatically detected situation: ${sit}${d.lowConfidence ? ' (low-confidence guess: check against the text)' : ''}.`);
    if (d.relation !== 'unknown') lines.push(`Likely relationship: ${REL_LABEL.en[d.relation]}.`);
  }
  const prof = bank && bank.profile && bank.profile[lg];
  if (prof) {
    const name = SIGN_NAMES[lg][sign];
    lines.push(lg === 'it'
      ? `Tratti tipici di chi è ${name} da usare come lente (non come verità), scegli solo ciò che si collega ai fatti:`
      : `Typical ${name} traits to use as a lens (not as truth); use only what connects to the facts:`);
    const LBL = lg === 'it'
      ? { need: 'Bisogno', trigger: 'Cosa lo/la fa chiudere', hurt: 'Come mostra la ferita', unlock: 'Cosa lo/la riapre', timing: 'Quando parlarne' }
      : { need: 'Need', trigger: 'Shuts down when', hurt: 'Shows hurt by', unlock: 'Opens up with', timing: 'Timing' };
    for (const k of ['need', 'trigger', 'hurt', 'unlock', 'timing']) {
      const a = arr(prof[k]);
      if (a.length) lines.push(`- ${LBL[k]}: ${a.join(' / ')}`);
    }
  }
  if (mine && !sign) lines.push(lg === 'it' ? `Il segno dell'utente è ${SIGN_NAMES.it[mine]}.` : `The user's own sign is ${SIGN_NAMES.en[mine]}.`);
  if (sign && mine) {
    const p = pairingLine(mine, sign, lg, 0);
    if (p) lines.push(lg === 'it' ? `Dinamica tra gli elementi (il segno dell'utente è ${SIGN_NAMES.it[mine]}): ${p}` : `Element dynamic (the user's sign is ${SIGN_NAMES.en[mine]}): ${p}`);
  }
  return { text: lines.join('\n'), situation: d.situation, relation: d.relation, sign, userSign: mine };
}

